class NoDataTransfer(Exception):
    """
    Raised when there is no data transfer progressing between client and server
    """
    pass


class UnexpectedError(Exception):
    """
    Raised when unexpected error occurred during operation
    """
    pass


class IncorrectWidgetText(Exception):
    """
    Raised when there is no option to select a given network mode
    """
    pass


class AttachShouldNotBePossible(Exception):
    """
    Raised when attach is possible but it should not be
    """
    pass
